-- Hide demo_default_target_user_id (a real user UUID) from anon/authenticated; only the service role reads it.
-- Least privilege: browser roles may only SELECT public columns; authenticated admins (RLS-gated) may UPDATE public columns.
revoke all on table public.site_settings from anon, authenticated;
grant select (id, public_app_url, updated_at, register_background_key, register_background_credit, login_background_key, login_background_credit, coming_soon_song_url, coming_soon_song_title, coming_soon_lyrics, coming_soon_revolution_lines, chat_background_key, chat_background_credit, challenge_enabled, challenge_intro_lines, challenge_intro_tts_url, challenge_intro_tts_text, challenge_eating_window_lesson, guide_rules) on public.site_settings to anon, authenticated;
grant update (id, public_app_url, updated_at, register_background_key, register_background_credit, login_background_key, login_background_credit, coming_soon_song_url, coming_soon_song_title, coming_soon_lyrics, coming_soon_revolution_lines, chat_background_key, chat_background_credit, challenge_enabled, challenge_intro_lines, challenge_intro_tts_url, challenge_intro_tts_text, challenge_eating_window_lesson, guide_rules) on public.site_settings to authenticated;
